const incoming = $input.first()?.json ?? {};
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const rawSeries = String(body.series ?? body.series_id ?? 'cup').trim().toLowerCase();
const seriesAliases = {
  '1': 1, cup: 1, 'cup series': 1, nascar: 1,
  '2': 2, xfinity: 2, oreilly: 2, "o'reilly": 2, 'xfinity series': 2,
  '3': 3, truck: 3, trucks: 3, 'truck series': 3, craftsman: 3,
};
const seriesId = seriesAliases[rawSeries] ?? 1;
const labels = { 1: 'NASCAR Cup Series', 2: "NASCAR O'Reilly Auto Parts Series", 3: 'NASCAR Craftsman Truck Series' };
const currentYear = Number(new Intl.DateTimeFormat('en-US', { timeZone: 'America/Chicago', year: 'numeric' }).format(new Date()));
const requestedSeason = Number.parseInt(String(body.season ?? body.race_season ?? currentYear), 10);
const season = Number.isInteger(requestedSeason) && requestedSeason >= 1948 && requestedSeason <= currentYear + 1
  ? requestedSeason
  : currentYear;
const requestedTop = Number.parseInt(String(body.top ?? body.limit ?? 5), 10);
const top = Number.isInteger(requestedTop) ? Math.min(10, Math.max(1, requestedTop)) : 5;
const requestedRaceId = Number.parseInt(String(body.race_id ?? body.raceId ?? ''), 10);
const raceId = Number.isInteger(requestedRaceId) && requestedRaceId > 0 ? requestedRaceId : null;
const scheduleUrl = seriesId === 1
  ? 'https://cf.nascar.com/cacher/' + season + '/1/race_list_basic.json'
  : 'https://cf.nascar.com/cacher/' + season + '/race_list_basic.json';

return [{ json: {
  action: 'scores',
  seriesId,
  series: labels[seriesId],
  season,
  top,
  raceId,
  scheduleUrl,
} }];

const request = $('Select Latest NASCAR Race').first().json;
const payload = $input.first()?.json ?? {};
const rawError = payload.error?.message ?? payload.error ?? request.error;
if (rawError) {
  const detail = String(rawError);
  return [{ json: {
    ok: false,
    message: 'NASCAR results are temporarily unavailable: ' + detail.slice(0, 240),
    error: detail.slice(0, 500),
    source: 'cf.nascar.com',
  } }];
}

const race = Array.isArray(payload.weekend_race) ? payload.weekend_race[0] : payload.weekend_race;
if (!race || !race.race_id) {
  return [{ json: {
    ok: false,
    message: 'NASCAR returned the season schedule but no detailed result for the selected race.',
    source: 'cf.nascar.com',
  } }];
}

const finishers = (Array.isArray(race.results) ? race.results : [])
  .filter((result) => Number(result.finishing_position) > 0)
  .sort((a, b) => Number(a.finishing_position) - Number(b.finishing_position))
  .slice(0, request.top)
  .map((result) => ({
    position: Number(result.finishing_position),
    driver: String(result.driver_fullname || result.driver_name || 'Unknown driver'),
    car: String(result.car_number || result.official_car_number || ''),
    make: String(result.car_make || result.manufacturer || ''),
    status: String(result.finishing_status || result.comment || ''),
    lapsCompleted: Number(result.laps_completed || 0),
    points: Number(result.points_earned || 0),
    disqualified: Boolean(result.disqualified),
  }));
const ordinal = (value) => {
  const mod100 = value % 100;
  if (mod100 >= 11 && mod100 <= 13) return value + 'th';
  return value + ({ 1: 'st', 2: 'nd', 3: 'rd' }[value % 10] || 'th');
};
const whenValue = race.race_date || race.date_scheduled || race.tunein_date;
const when = Number.isFinite(Date.parse(whenValue || ''))
  ? new Intl.DateTimeFormat('en-US', { timeZone: 'America/Chicago', month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(whenValue))
  : String(request.season);
const raceName = String(race.race_name || 'NASCAR race');
const track = race.track_name ? ' at ' + race.track_name : '';
const leaders = finishers.length
  ? finishers.map((result) => ordinal(result.position) + ', ' + result.driver + (result.car ? ' in the number ' + result.car : '')).join('; ')
  : 'Official finishing positions are not available yet.';
const message = 'Latest ' + request.series + ' result: ' + raceName + track + ' on ' + when + '. ' + leaders + '.';

return [{ json: {
  ok: true,
  message,
  source: 'cf.nascar.com',
  series: request.series,
  season: request.season,
  race: {
    id: Number(race.race_id),
    name: raceName,
    track: String(race.track_name || ''),
    date: whenValue || null,
    scheduledLaps: Number(race.scheduled_laps || 0),
    actualLaps: Number(race.actual_laps || 0),
    inspectionComplete: Boolean(race.inspection_complete),
  },
  finishers,
} }];

const request = $('Prepare NASCAR Request').first().json;
const inputs = $input.all().map((item) => item.json ?? {});
const payload = inputs[0] ?? {};
const error = payload.error?.message ?? payload.error;
if (error) {
  return [{ json: { ...request, error: String(error), resultUrl: null } }];
}

const races = inputs.length > 1 && inputs.every((item) => item && item.race_id)
  ? inputs
  : Array.isArray(payload)
    ? payload
  : Array.isArray(payload['series_' + request.seriesId])
    ? payload['series_' + request.seriesId]
    : [];
const requested = request.raceId
  ? races.find((race) => Number(race.race_id) === request.raceId)
  : null;
const now = Date.now();
const completed = races
  .filter((race) => {
    const start = Date.parse(race.race_date || race.date_scheduled || race.tunein_date || '');
    return Number.isFinite(start) && start <= now && (race.inspection_complete || Number(race.winner_driver_id) > 0);
  })
  .sort((a, b) => Date.parse(b.race_date || b.date_scheduled) - Date.parse(a.race_date || a.date_scheduled));
const race = requested || completed[0] || null;
const resultUrl = race
  ? 'https://cf.nascar.com/cacher/' + request.season + '/' + request.seriesId + '/' + race.race_id + '/weekend-feed.json'
  : null;

return [{ json: {
  ...request,
  selectedRace: race,
  resultUrl,
  error: race ? null : 'No completed race was found in the NASCAR season feed',
} }];
